export default function Footer() {
  return (
    <footer className="bg-green-900 text-white py-6 mt-16">
      <div className="container mx-auto text-center">
        <p className="text-sm">
          © {new Date().getFullYear()} Sikkim Monasteries Digital Platform. All
          Rights Reserved.
        </p>
        <p className="mt-2 text-xs">
          Built with ❤️ to preserve culture & heritage.
        </p>
      </div>
    </footer>
  );
}
